SELECT DATE_FORMAT(c.signup_date, 'yyyy-MM') AS signup_month, SUM(CASE WHEN s.plan = 'enterprise' THEN s.monthly_fee ELSE 0 END) AS enterprise_monthly_fee, ROUND(STDDEV(s.monthly_fee), 2) AS stddev_monthly_fee FROM subscriptions s LEFT OUTER JOIN customers c ON s.customer_id = c.id GROUP BY DATE_FORMAT(c.signup_date, 'yyyy-MM') ORDER BY stddev_monthly_fee DESC, signup_month LIMIT 1;
